(async()=>{'use strict';const keys=['zuxuru-fashion-service-v1','zuxuru-fashion-growth-v1','zuxuru-designer-work-v1'],scripts=['workflow-run-gate.js','media-image-editor.js','storefront-editor.js','designer-media.js','fashion-service.js','garment-pricing.js','designer-next-step.js','designer-dashboard.js','fashion-growth.js','work-agenda.js','designer-work.js','designer-health.js','designer-evidence.js','designer-publish.js','designer-engine.js','designer-run.js','business-console.js','studio-campaigns.js'];const $=id=>document.getElementById(id),nativeSet=Storage.prototype.setItem;let revision=0,ready=false,busy=false,pending=false,timer,userId='',loaded=false,conflict=false;const status=text=>$('cloud-status').textContent=text;
const empty=()=>({[keys[0]]:{designer:{},products:[],evidence:[],orders:[]},[keys[1]]:{partners:[],prospects:[],metrics:[]},[keys[2]]:{tasks:[],studio:[]}});function payload(){const p=empty();for(const k of keys){try{const v=JSON.parse(localStorage.getItem(k));if(v)p[k]=v;}catch{}}return p;}
function draft(){try{if(userId)nativeSet.call(localStorage,'zuxuru-cloud-draft-'+userId,JSON.stringify({revision,payload:payload()}));}catch{status('Draft backup failed: browser storage is full. Export your draft now.');}}
$('cloud-export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify({format:'zuxuru-cloud-draft',revision,payload:payload()},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='zuxuru-unsaved-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
async function loadApps(){if(loaded)return;for(const src of scripts){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=reject;document.head.append(script);});}loaded=true;}
async function save(){if(!ready||busy||conflict)return;busy=true;pending=false;let succeeded=false;status('Saving your designer records to the cloud…');try{const response=await fetch('/api/designer/workspace',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({revision,payload:payload()})});const result=await response.json();if(!response.ok){if(response.status===409)conflict=true;throw Error(result.error||'Cloud save failed.');}revision=result.revision;succeeded=true;status('Cloud saved · '+new Date(result.updatedAt).toLocaleString());if(!pending)localStorage.removeItem('zuxuru-cloud-draft-'+userId);else draft();}catch(e){pending=true;draft();status(e.message+' Your unsaved draft remains on this device.');}finally{busy=false;if(pending&&succeeded&&!conflict){clearTimeout(timer);timer=setTimeout(save,0);}else if(pending&&!conflict)status('Not cloud saved. Export your draft or choose Retry cloud save.');}}
window.addEventListener('studio-workspace-updated',()=>{conflict=true;clearTimeout(timer);status('Studio saved a new follow-up task. Open it from Studio to reload your daily work. Export any unsaved dashboard draft first.');});window.designerCloudReady=()=>ready&&!busy&&!pending&&!conflict&&!window.bongaRunGate?.active();
$('cloud-retry').onclick=()=>{if(conflict){status('Conflict: export your draft, then reload. The other device’s cloud records will not be overwritten.');return;}if(!ready)location.reload();else save();};
Storage.prototype.setItem=function(k,v){nativeSet.call(this,k,v);if(this===localStorage&&keys.includes(k)&&ready){pending=true;draft();status('Unsaved changes — cloud save pending.');clearTimeout(timer);timer=setTimeout(save,500);}};
window.addEventListener('beforeunload',event=>{if(pending||busy){event.preventDefault();event.returnValue='';}});
try{const response=await fetch('/api/designer/workspace');const data=await response.json();if(!response.ok)throw Error(data.error||'Cloud unavailable.');revision=data.revision;userId=data.userId;const old=localStorage.getItem('zuxuru-cloud-user');if(old&&old!==userId)keys.forEach(k=>localStorage.removeItem(k));nativeSet.call(localStorage,'zuxuru-cloud-user',userId);
let cache;try{cache=JSON.parse(localStorage.getItem('zuxuru-cloud-draft-'+userId));}catch{}
if(data.payload){let incoming=data.payload;if(cache&&cache.revision===revision&&cache.payload){incoming=cache.payload;pending=true;status('Recovered unsaved draft. Review it, then choose Retry cloud save.');}else if(cache){status('Cloud records loaded. An older draft exists on this device; export it before replacing it.');$('cloud-export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(cache,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='zuxuru-older-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};}else status('Cloud account opened. Changes save to this account.');for(const k of keys)nativeSet.call(localStorage,k,JSON.stringify(incoming[k]||empty()[k]));ready=true;await loadApps();}
else{status('Your cloud account is ready. Choose whether to upload your existing browser work or start fresh.');$('cloud-migrate').hidden=false;$('cloud-fresh').hidden=false;const start=async fresh=>{if(fresh)for(const k of keys)nativeSet.call(localStorage,k,JSON.stringify(empty()[k]));ready=true;await save();$('cloud-migrate').hidden=true;$('cloud-fresh').hidden=true;await loadApps();};$('cloud-migrate').onclick=()=>start(false);$('cloud-fresh').onclick=()=>{if(confirm('Start with an empty workspace? Export existing browser work first if you need it.'))start(true);};}
}catch(e){status(e.message+' Designer tools are paused to avoid showing unsaved records as live.');}
})();
